style.css:
@-moz-document domain("character.ai") {
/* 01. Character.AI Hacker Green Glass v1.0.1. ChatGPT v1.5.6 palette and exact grid. No external assets or font downloads. */
html, html.dark, html.light, html[data-theme="dark"], html[data-theme="light"] {
  --background: 150 15% 4% !important;
  --foreground: 140 100% 93% !important;
  --primary: 144 100% 50% !important;
  --primary-foreground: 143 100% 5% !important;
  --secondary: 145 54% 13% !important;
  --secondary-foreground: 140 100% 90% !important;
  --muted: 145 35% 12% !important;
  --muted-foreground: 141 43% 68% !important;
  --accent: 144 65% 18% !important;
  --accent-foreground: 140 100% 94% !important;
  --popover: 144 66% 5% !important;
  --popover-foreground: 140 100% 93% !important;
  --card: 145 54% 8% !important;
  --card-foreground: 140 100% 93% !important;
  --border: 143 48% 26% !important;
  --input: 143 48% 26% !important;
  --ring: 144 100% 50% !important;
  --destructive: 0 75% 58% !important;
  --destructive-foreground: 0 0% 100% !important;
  --surface-elevation-1: 145 48% 8% !important;
  --surface-elevation-2: 145 48% 11% !important;
  --surface-elevation-3: 145 48% 15% !important;
  --button-filled: 144 100% 45% !important;
  --outline: 145 48% 8% !important;
  --border-outline: 143 48% 26% !important;
  --font-sans: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", Consolas, "Lucida Console", "Courier New", monospace !important;
  --font-mono: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", Consolas, "Lucida Console", "Courier New", monospace !important;
  color-scheme: dark !important;
  color: #d9ffe6 !important;
  background-color: #0a0a0a !important;
  background-image: linear-gradient(to right, rgba(130,255,167,.13) 1px, transparent 1px), linear-gradient(to bottom, rgba(130,255,167,.13) 1px, transparent 1px), repeating-linear-gradient(to bottom, rgba(10,10,10,0) 0px, rgba(10,10,10,0) 3px, rgba(105,255,153,.035) 3px, rgba(105,255,153,.035) 4px) !important;
  background-size: 40px 40px, 40px 40px, 100% 4px !important;
  background-position: 0 0 !important;
  background-repeat: repeat !important;
  background-attachment: fixed !important;
}

/* NextUI / HeroUI token bridge. These use HSL component values, not hex strings. */
html, body, .dark, .light {
  --nextui-background: 150 15% 4% !important;
  --nextui-foreground: 140 100% 93% !important;
  --nextui-primary: 144 100% 45% !important;
  --nextui-primary-foreground: 143 100% 5% !important;
  --nextui-secondary: 145 54% 15% !important;
  --nextui-secondary-foreground: 140 100% 93% !important;
  --nextui-focus: 144 100% 50% !important;
  --nextui-divider: 143 48% 26% !important;
  --nextui-content1: 145 48% 8% !important;
  --nextui-content2: 145 48% 11% !important;
  --nextui-content3: 145 48% 15% !important;
  --nextui-content4: 145 48% 20% !important;
  --nextui-default: 145 40% 16% !important;
  --nextui-default-foreground: 140 100% 93% !important;
  --nextui-default-100: 145 40% 9% !important;
  --nextui-default-200: 145 40% 14% !important;
  --nextui-default-300: 145 40% 22% !important;
  --nextui-default-400: 141 25% 48% !important;
  --nextui-default-500: 141 35% 62% !important;
  --heroui-background: 150 15% 4% !important;
  --heroui-foreground: 140 100% 93% !important;
  --heroui-primary: 144 100% 45% !important;
  --heroui-primary-foreground: 143 100% 5% !important;
  --heroui-secondary: 145 54% 15% !important;
  --heroui-secondary-foreground: 140 100% 93% !important;
  --heroui-focus: 144 100% 50% !important;
  --heroui-divider: 143 48% 26% !important;
  --heroui-content1: 145 48% 8% !important;
  --heroui-content2: 145 48% 11% !important;
  --heroui-content3: 145 48% 15% !important;
  --heroui-content4: 145 48% 20% !important;
  --heroui-default: 145 40% 16% !important;
  --heroui-default-foreground: 140 100% 93% !important;
  --heroui-default-100: 145 40% 9% !important;
  --heroui-default-200: 145 40% 14% !important;
  --heroui-default-300: 145 40% 22% !important;
  --heroui-default-400: 141 25% 48% !important;
  --heroui-default-500: 141 35% 62% !important;
}

/* 02. Clear canvas. Preserve native dimensions, placement and stacking. */
body, #root, #__next, main, #main-content, [class~="bg-background"], [class~="dark:bg-background"], div[class~="dark:bg-[#18181B]"] {
  background-color: transparent !important;
  background-image: none !important;
  color: #d9ffe6 !important;
}
body, button, input, textarea, select, [contenteditable="true"], [role="textbox"], .font-sans, .font-serif, h1, h2, h3, h4, h5, h6, p, label, a, li, dt, dd, th, td, .prose, .markdown {
  font-family: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", Consolas, "Lucida Console", "Courier New", monospace !important;
  font-variant-ligatures: none !important;
}
::selection {
  background: rgba(0,255,102,.30) !important;
  color: #f0fff5 !important;
}

/* 03. Semantic text utilities. Leave multicolor images and provider icons alone. */
[class~="text-foreground"], [class~="text-primary"], [class~="dark:text-white"], [class~="text-white"], [class~="text-black"], [class~="text-gray-800"], [class~="text-default-900"], [class~="text-content1-foreground"] {
  color: #d9ffe6 !important;
}
[class~="text-muted-foreground"], [class~="text-default-500"], [class~="text-default-400"], [class~="text-gray-500"], small, time {
  color: #9ee5b6 !important;
}
a {
  color: #9affbc !important;
  text-decoration-color: rgba(0,255,102,.48) !important;
}
a:hover {
  color: #e7fff0 !important;
}
hr, [class~="border-border"], [class~="border-border-outline"], [class~="divide-border"] > * {
  border-color: rgba(49,235,115,.30) !important;
}

/* 04. Sidebar, header and native navigation surfaces. */
aside, [data-testid="sidebar"], [data-slot="sidebar"], nav[aria-label="Main"], nav[aria-label="Main navigation"] {
  background: linear-gradient(145deg, rgba(13,92,47,.35), rgba(1,19,11,.78)) !important;
  background-color: rgba(2,24,13,.58) !important;
  border-right: 1px solid rgba(67,255,134,.55) !important;
  box-shadow: inset -1px 0 0 rgba(120,255,164,.12), 5px 0 24px rgba(0,225,88,.10) !important;
}
header, [class~="fixed"][class~="top-0"][class~="bg-background"] {
  background-color: rgba(1,20,9,.94) !important;
  border-bottom-color: rgba(67,255,134,.35) !important;
}
aside a, nav a, [data-testid="sidebar"] a {
  color: #c0ffd5 !important;
  border-radius: 9px !important;
}
aside a:hover, nav a:hover, aside button:hover, nav button:hover, a[aria-current="page"] {
  background-color: rgba(17,117,53,.42) !important;
  color: #effff4 !important;
  box-shadow: inset 2px 0 0 rgba(0,255,102,.76) !important;
}

/* 05. Surface utilities cover discovery, profile, settings, login and chat cards. Flat selectors, no nesting or relational selectors. */
[class~="bg-surface-elevation-1"], [class~="bg-surface-elevation-2"], [class~="bg-surface-elevation-3"], [class~="dark:bg-surface-elevation-1"], [class~="dark:bg-surface-elevation-2"], [class~="dark:bg-surface-elevation-3"], [class~="bg-card"], [class~="bg-content1"], [class~="bg-content2"], [class~="bg-default-100"], [class~="bg-default-50"], div[class~="bg-white"], div[class~="bg-[#FAFAFA]"] {
  background-color: rgba(3,39,22,.78) !important;
  background-image: linear-gradient(135deg, rgba(17,92,49,.23), rgba(1,24,14,.34)) !important;
  color: #d9ffe6 !important;
  border-color: rgba(76,255,137,.39) !important;
}
[data-slot="card"], [data-testid="character-card"], [data-testid="chat-card"], article, a[href^="/character/"][class*="rounded"], a[href^="/chat/"][class*="rounded"], div[class~="dark:bg-surface-elevation-2"][class*="rounded"] {
  background-color: rgba(3,39,22,.76) !important;
  background-image: linear-gradient(135deg, rgba(17,92,49,.23), rgba(1,24,14,.34)) !important;
  border: 1px solid rgba(76,255,137,.43) !important;
  box-shadow: inset 0 1px 0 rgba(178,255,199,.15), 0 7px 22px rgba(0,0,0,.22) !important;
  color: #d9ffe6 !important;
}
[data-slot="card"]:hover, [data-testid="character-card"]:hover, a[href^="/character/"][class*="rounded"]:hover, a[href^="/chat/"][class*="rounded"]:hover {
  border-color: #65ff9f !important;
  box-shadow: 0 0 18px rgba(0,255,102,.18) !important;
}

/* 06. Message bubbles and markdown. Hook fallbacks cover several client layouts; no dimensions are forced. */
[data-testid="user-message"], [data-message-author-role="user"], [class~="bg-message-user"], [class~="bg-user-message"] {
  background: linear-gradient(140deg, rgba(22,116,60,.45), rgba(2,29,18,.78)) !important;
  border: 1px solid rgba(81,255,142,.50) !important;
  border-radius: 18px 18px 7px 18px !important;
  color: #e0ffeb !important;
  box-shadow: inset 0 1px 0 rgba(180,255,202,.15) !important;
}
[data-testid="character-message"], [data-testid="bot-message"], [data-message-author-role="assistant"], [class~="bg-message-bot"], [class~="bg-character-message"] {
  background: linear-gradient(135deg, rgba(17,92,49,.33), rgba(1,24,14,.76)) !important;
  border: 1px solid rgba(76,255,137,.40) !important;
  border-radius: 18px !important;
  color: #d9ffe6 !important;
}
.prose, .markdown, [data-testid="message-text"], [class~="text-primary-foreground"] {
  color: #d3fbe0 !important;
}
.prose a, .markdown a {
  color: #68ffa3 !important;
}
.prose em, .markdown em {
  color: #a5d8b7 !important;
}

/* 07. Form fields and composer. Never alter textarea height, overflow or native send positioning. */
textarea, input[type="text"], input[type="search"], input[type="email"], input[type="password"], input[type="number"], input[type="url"], select, [role="textbox"], [role="searchbox"], [role="combobox"], [contenteditable="true"], [data-slot="input-wrapper"] {
  background-color: rgba(2,28,15,.93) !important;
  color: #e0ffea !important;
  border-color: rgba(61,239,119,.44) !important;
  caret-color: #38ff82 !important;
}
[data-testid="chat-input-container"], [data-testid="message-input-container"], [data-slot="input-wrapper"] {
  background-image: linear-gradient(125deg, rgba(21,100,54,.22), rgba(1,20,13,.26)) !important;
  border: 1px solid rgba(85,255,143,.59) !important;
  box-shadow: inset 0 1px 0 rgba(181,255,200,.16), 0 0 20px rgba(0,255,105,.10) !important;
}
input::placeholder, textarea::placeholder {
  color: #8ecba4 !important;
  opacity: 1 !important;
}
[contenteditable="true"][data-placeholder]:empty::before {
  color: #8ecba4 !important;
}

/* 08. Buttons, tabs, chips and active/disabled states. */
button, [role="button"], [data-slot="chip"] {
  color: #b7ffd0 !important;
  border-color: rgba(45,226,108,.36) !important;
}
button[class~="bg-primary"], button[class~="bg-button-filled"], [role="button"][class~="bg-primary"], button[type="submit"], button[aria-label="Send message"], button[aria-label="Send Message"], button[aria-label="Send"] {
  background-color: #00e85c !important;
  background-image: none !important;
  color: #001b09 !important;
  box-shadow: 0 0 12px rgba(0,255,102,.22) !important;
}
button[class~="bg-primary"] *, button[class~="bg-button-filled"] *, button[type="submit"] *, button[aria-label="Send message"] * {
  color: inherit !important;
}
button[class~="bg-outline"], button[class~="bg-secondary"], [data-slot="chip"], [role="tab"] {
  background-color: rgba(4,43,20,.91) !important;
  color: #c7ffda !important;
}
button:hover, [role="button"]:hover, button[data-hover="true"] {
  border-color: rgba(85,255,143,.76) !important;
}
button[class~="bg-primary"]:hover, button[class~="bg-button-filled"]:hover, button[type="submit"]:hover {
  background-color: #49ff90 !important;
  color: #001b09 !important;
}
[role="tab"][aria-selected="true"], [data-selected="true"][role="option"], [role="switch"][aria-checked="true"] {
  background-color: rgba(12,103,43,.88) !important;
  color: #f0fff5 !important;
  border-color: #00e85c !important;
}
button:focus-visible, a:focus-visible, input:focus-visible, textarea:focus-visible, select:focus-visible, [role="button"]:focus-visible, [contenteditable="true"]:focus-visible {
  outline: 2px solid #00ff66 !important;
  outline-offset: 2px !important;
}
button:disabled, [aria-disabled="true"] {
  opacity: .50 !important;
}
input[type="checkbox"], input[type="radio"], input[type="range"] {
  accent-color: #00e85c !important;
}

/* 09. Menus/dialogs intentionally use near-opaque glass for readability. Do not paint the positioning wrapper around a popup. */
[role="menu"], [role="listbox"], [role="dialog"], [role="alertdialog"], [role="tooltip"], [data-slot="popover-content"], [data-slot="modal"], [data-slot="tooltip-content"], [data-radix-menu-content], [data-sonner-toast], .Toastify__toast {
  background: rgba(1,23,10,.98) !important;
  border: 1px solid rgba(61,239,119,.48) !important;
  color: #d9ffe6 !important;
  box-shadow: 0 12px 35px rgba(0,0,0,.62), inset 0 1px 0 rgba(160,255,185,.10) !important;
}
[role="dialog"] [class~="bg-background"], [role="menu"] [class~="bg-background"] {
  background-color: transparent !important;
}
[data-slot="backdrop"], [data-state="open"][class~="bg-black/50"] {
  background-color: rgba(0,8,3,.72) !important;
}
[role="menuitem"], [role="menuitemradio"], [role="menuitemcheckbox"], [role="option"] {
  color: #cef9dc !important;
}
[role="menuitem"]:hover, [role="menuitemradio"]:hover, [role="menuitemcheckbox"]:hover, [role="option"]:hover, [role="menuitem"][data-highlighted], [role="option"][data-highlighted], [data-slot="listbox-item"][data-hover="true"] {
  background-color: rgba(12,103,43,.80) !important;
  color: #f0fff5 !important;
}

/* 10. Brand glow is behind the original glyphs; no glowing overlay pseudo-elements. */
a[href="/"] svg, a[href="/"] img, [aria-label="Character.AI"] svg, [aria-label="character.ai"] svg {
  color: #00ff66 !important;
  filter: drop-shadow(0 0 4px rgba(0,255,102,.75)) drop-shadow(0 0 12px rgba(0,255,102,.32)) !important;
}

/* 11. Code, quotes, tables and separators. */
pre, pre code {
  background-color: rgba(1,17,9,.96) !important;
  color: #bfffd0 !important;
  font-family: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", Consolas, "Lucida Console", "Courier New", monospace !important;
}
pre {
  border: 1px solid rgba(27,222,94,.29) !important;
  border-radius: 9px !important;
}
p code, li code, td code {
  background-color: rgba(5,57,23,.78) !important;
  color: #90ffc0 !important;
}
blockquote {
  border-left-color: #00e85c !important;
  background-color: rgba(4,45,22,.44) !important;
}
th, td {
  border-color: rgba(49,211,110,.28) !important;
}
th {
  background-color: rgba(5,48,21,.82) !important;
}

/* 12. Matching scrollbars in Firefox and Chromium. No fixed decorative overlays, animation or backdrop blur. */
* {
  scrollbar-color: #248c4b #07160d !important;
  scrollbar-width: thin !important;
}
::-webkit-scrollbar {
  width: 10px !important;
  height: 10px !important;
}
::-webkit-scrollbar-track {
  background: #07160d !important;
}
::-webkit-scrollbar-thumb {
  background: #248c4b !important;
  border: 2px solid #07160d !important;
  border-radius: 10px !important;
}
::-webkit-scrollbar-thumb:hover {
  background: #47d577 !important;
}
::-webkit-scrollbar-corner {
  background: #07160d !important;
}

/* 13. Chat details: exact container from supplied Character.AI markup.
   One tinted panel behind character information and chat controls.
   Keep native responsive visibility, scrolling, width and positioning. */
body #chat-details {
  background-color: rgba(2, 27, 14, .92) !important;
  background-image: linear-gradient(145deg, rgba(15, 76, 39, .28), rgba(1, 18, 10, .18)) !important;
  color: #d9ffe6 !important;
  border: 1px solid rgba(76, 255, 137, .42) !important;
  border-radius: 16px !important;
  box-shadow: inset 0 1px 0 rgba(178, 255, 199, .14), inset 0 0 24px rgba(0, 20, 9, .20) !important;
}
}
